import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_CART_DRAWER_RECIPE = 'ZimmCartDrawer';

// SFCC-315 builds the drawer shell only — SFCC-277/272 (later commits in this same 18-commit
// plan) will replace this with the real empty-bag component. This placeholder exists only so
// the body isn't blank/broken-looking in the meantime.
const EMPTY_BAG_PLACEHOLDER_TEXT = 'Your bag is empty.';

export type ZimmCartDrawerProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via ZimmDrawer/Chakra's Drawer). */
  onClose: () => void;
  /** Number of line items in the bag. Drives the header title ("BAG • {itemCount}" vs
   *  "YOUR BAG IS EMPTY") and whether `children` or the interim empty-state placeholder renders. */
  itemCount: number;
  /** Element to focus once the drawer finishes closing — see ZimmDrawer's own doc (AC10
   *  focus-return); without this Chakra falls back to focusing document.body. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Cart line items. This organism owns no item-rendering logic itself — the caller supplies
   *  the list (SFCC-270's ProductItem, wired in a later commit in this same plan). Rendered only
   *  while itemCount > 0. */
  children: React.ReactNode;
  /** Reserved slot for SFCC-404's message-aggregation system (validation/error/promo banners).
   *  Always rendered, even with nothing passed — see zimmCartDrawer.css.ts's `messages` part:
   *  the band reserves height regardless, so the drawer doesn't change position when a message
   *  appears or disappears. */
  messages?: React.ReactNode;
  /** Reserved slot for SFCC-275's button group (checkout / continue shopping). Not built in this
   *  commit (SFCC-315 is shell-only) — this organism only provides the slot it will render into
   *  later. */
  footer?: React.ReactNode;
};

/**
 * SFCC-315 — the Cart drawer shell. Wraps ZimmDrawer (size="xLarge") with the cart-specific
 * header title, a height-reserving messages band, a responsive items/totals layout, and a
 * footer slot.
 *
 * Deliberately not wired to a trigger yet — no `_app`/`product-view` changes, no
 * `useCartDrawer` hook, no button-group content, no real empty-state body, no message
 * aggregation. All of those are separate, later commits in this same 18-commit plan — this
 * organism is exercised only via its own Storybook stories today.
 *
 * @param props see ZimmCartDrawerProps
 */
export const ZimmCartDrawer = ({
  isOpen,
  onClose,
  itemCount,
  finalFocusRef,
  children,
  messages,
  footer,
}: ZimmCartDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_CART_DRAWER_RECIPE, {});
  const title = itemCount === 0 ? 'YOUR BAG IS EMPTY' : `BAG • ${itemCount}`;

  return (
    <ZimmDrawer isOpen={isOpen} onClose={onClose} size="xLarge" title={title} finalFocusRef={finalFocusRef}>
      <chakra.div __css={styles.messages}>{messages}</chakra.div>
      <chakra.div __css={styles.body}>
        {itemCount === 0 ? <chakra.p textStyle="body2">{EMPTY_BAG_PLACEHOLDER_TEXT}</chakra.p> : children}
      </chakra.div>
      <chakra.div __css={styles.footer}>{footer}</chakra.div>
    </ZimmDrawer>
  );
};

import { breakpoints } from 'app/theme/foundation';

// SFCC-315 (Cart drawer): items/totals column widths for the desktop (above the desktop
// breakpoint) two-column layout, per the approved build-step spec (not independently
// re-verified against a Figma node by this commit — see this build step's own instructions) —
// no --zimm-scale equivalent at either value yet.
// audit-allow: fixed column widths from the approved build-step spec, pending a foundation token.
const ITEMS_COLUMN_WIDTH = '22.5rem'; // 360px
const TOTALS_COLUMN_WIDTH = '26.875rem'; // 430px

// gridSystem.ts names `md` "the tablet breakpoint" (768px) and `xl` "the desktop breakpoint"
// (1280px) — reusing both aliases rather than inventing a third, per this component's own
// build-step scope note.
//
// The media-query string is inlined at each use site below (matching zimmDrawer.css.ts's own
// `[`@media (min-width: ${breakpoints.md})`]:` usage) rather than hoisted to a shared const,
// purely for readability/DRY-ness at the definition site — it makes no difference to how this
// file type-checks either way (verified via `npx tsc --noEmit`). Each part below mixes plain
// mobile-default properties with media-query-keyed overrides, so TypeScript resolves any
// bracket access into this object (e.g. `body[someMediaQueryString]`) to the union of every
// property-value shape in it, not the one specific shape that's actually there at runtime —
// see zimmCartDrawer.css.test.ts's own comment on the resulting `.toEqual(...)` workaround.

export const ZimmCartDrawer = {
  parts: ['messages', 'body', 'footer'],
  baseStyle: {
    // Reserves height even with nothing to show — designer requirement: "to prevent the cart
    // changing position depending on errors". --zimm-scale-1300 = 52px (zimmTokens.ts:168).
    messages: {
      minHeight: 'var(--zimm-scale-1300)',
      paddingInline: 'var(--zimm-scale-2xl)', // 32px — mobile/tablet page gutter
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingInline: 'var(--zimm-scale-6xl)', // 128px — desktop page gutter
      },
    },
    // Mobile default: full-width single column, 32px gutter (spacing['2xl']).
    body: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      paddingInline: 'var(--zimm-scale-2xl)',
      // Tablet step restated explicitly at its own breakpoint (same values as the mobile
      // default above — fluid width, NOT a computed pixel width) — see
      // .claude/rules/overrideStyling.md's "Responsive steps are explicit media queries".
      [`@media (min-width: ${breakpoints.md})`]: {
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        paddingInline: 'var(--zimm-scale-2xl)',
      },
      // Desktop: two columns (items/totals), a 140px gap between them, and a 128px page gutter
      // each side.
      [`@media (min-width: ${breakpoints.xl})`]: {
        display: 'grid',
        gridTemplateColumns: `${ITEMS_COLUMN_WIDTH} ${TOTALS_COLUMN_WIDTH}`,
        columnGap: 'var(--zimm-scale-3500)', // 140px
        paddingInline: 'var(--zimm-scale-6xl)', // 128px
      },
    },
    // No button-group content yet (SFCC-275, a later commit) — this part only carries the page
    // gutter so the slot lines up with `messages`/`body` above it once that content lands.
    footer: {
      paddingInline: 'var(--zimm-scale-2xl)',
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingInline: 'var(--zimm-scale-6xl)',
      },
    },
  },
};

