import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { chakra } from '@chakra-ui/react';
import { expect, within } from 'storybook/test';
import { ZimmCartDrawer } from './index';

const meta: Meta<typeof ZimmCartDrawer> = {
  title: 'Layout/ZimmCartDrawer',
  component: ZimmCartDrawer,
};
export default meta;
type Story = StoryObj<typeof ZimmCartDrawer>;

/**
 * SFCC-315 shell only — no trigger, no real item list, no button-group footer content (all
 * later commits in this same plan). `children`/`footer` below are placeholder content so the
 * slots are visibly non-empty, not a preview of their eventual real components.
 */
const CartDrawerExample = ({ itemCount }: { itemCount: number }) => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmCartDrawer
      isOpen={isOpen}
      onClose={() => setIsOpen(false)}
      itemCount={itemCount}
      footer={<chakra.p padding="var(--zimm-scale-m)">Footer slot placeholder — SFCC-275's button group lands here later.</chakra.p>}
    >
      <chakra.p padding="var(--zimm-scale-xl)">Cart line items render here — SFCC-270's ProductItem list is wired in by a later commit.</chakra.p>
    </ZimmCartDrawer>
  );
};

export const Default: Story = {
  render: () => <CartDrawerExample itemCount={3} />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md's Layer-2 exception (see ZimmDrawer's
    // own stories for the same reasoning: Chakra's Drawer/Modal renders via a Portal appended to
    // document.body, and .storybook/preview.tsx configures no custom portal container).
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog', { name: 'BAG • 3' });
    await expect(dialog).toBeInTheDocument();
  },
};

export const Empty: Story = {
  render: () => <CartDrawerExample itemCount={0} />,
  play: async () => {
    const doc = within(document.body);
    const dialog = await doc.findByRole('dialog', { name: 'YOUR BAG IS EMPTY' });
    await expect(dialog).toBeInTheDocument();
  },
};

