import React, { useId, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';
import type { ZimmDrawerSize } from 'app/components/ui-kits/atoms/zimmDrawer';
import { ZimmTabs } from 'app/components/ui-kits/molecules/zimmTabs';
import type { ZimmTabItem } from 'app/components/ui-kits/molecules/zimmTabs';

const ZIMM_PDP_DRAWER_RECIPE = 'ZimmPdpDrawer';

export type ZimmPdpDrawerTab = ZimmTabItem & {
  content: React.ReactNode;
};

type ZimmPdpDrawerProps = {
  isOpen: boolean;
  onClose: () => void;
  size: ZimmDrawerSize;
  /** SFCC-266's EU Environmental Qualities tab, SFCC-102's Size Guide, etc. all pass their own
   *  content component here — this organism owns none of it (SFCC-736's scope is shell only). */
  tabs: ZimmPdpDrawerTab[];
  /** Which tab is active when the drawer mounts — e.g. the tab the triggering info-link maps to.
   *  Only read on first mount; pass a `key` at the call site to force a reset on reopen with a
   *  different starting tab. */
  initialTabId?: string;
  /** No visible title exists in the tabbed header (unlike a plain-title drawer), so this is
   *  required rather than filled with placeholder copy. */
  ariaLabel: string;
};

/**
 * The SFCC-736 pdp/drawer deliverable — composes ZimmDrawer (shell) with ZimmTabs (nav header)
 * and swaps content by active tab. Renders the shell even with an empty `tabs` array (AC 11).
 *
 * @param props see ZimmPdpDrawerProps
 */
export const ZimmPdpDrawer = ({ isOpen, onClose, size, tabs, initialTabId, ariaLabel }: ZimmPdpDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_PDP_DRAWER_RECIPE, { variant: size });
  // `initialTabId` only wins when it actually matches one of `tabs` — an id from a stale caller
  // or a typo would otherwise select no tab at all, and ZimmTabs gives every tab `tabIndex={-1}`
  // when none is active, so keyboard users could never enter the tablist.
  const initialTab = tabs.find((tab) => tab.id === initialTabId);
  const [activeTabId, setActiveTabId] = useState(initialTab?.id ?? tabs[0]?.id ?? '');
  // Shared with ZimmTabs (as `idPrefix`) so each tab's `id`/`aria-controls` and this panel's
  // `id`/`aria-labelledby` reference each other correctly — `useId()` keeps it unique even with
  // more than one tabbed drawer mounted at once (this page also mounts an untabbed ZimmDrawer).
  const idPrefix = useId();

  const activeTab = tabs.find((tab) => tab.id === activeTabId);

  return (
    <ZimmDrawer isOpen={isOpen} onClose={onClose} size={size} aria-label={ariaLabel}>
      {tabs.length > 0 && (
        <ZimmTabs
          tabs={tabs}
          activeTabId={activeTabId}
          onTabChange={setActiveTabId}
          size={size}
          ariaLabel={ariaLabel}
          idPrefix={idPrefix}
        />
      )}
      {activeTab ? (
        <chakra.div
          id={`${idPrefix}-panel`}
          role="tabpanel"
          aria-labelledby={`${idPrefix}-tab-${activeTabId}`}
          tabIndex={0}
          __css={styles.content}
        >
          {activeTab.content}
        </chakra.div>
      ) : (
        // AC 11 — zero tabs (or an activeTabId with no matching tab) still renders the shell,
        // but with no tab to relate a panel to, `role="tabpanel"`/`aria-labelledby` would
        // reference a nonexistent tab id — a plain container carries no such claim.
        <chakra.div __css={styles.content} />
      )}
    </ZimmDrawer>
  );
};

