import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { chakra } from '@chakra-ui/react';
import { expect, userEvent, within } from 'storybook/test';
import { ZimmPdpDrawer } from './index';
import type { ZimmPdpDrawerTab } from './index';

const meta: Meta<typeof ZimmPdpDrawer> = {
  title: 'Commerce/ZimmPdpDrawer',
  component: ZimmPdpDrawer,
};
export default meta;
type Story = StoryObj<typeof ZimmPdpDrawer>;

const SectionHeading = ({ children }: { children: React.ReactNode }) => (
  <chakra.h3 textStyle="body1Strong" marginBottom="var(--zimm-scale-l)">
    {children}
  </chakra.h3>
);

const DetailsAndCareContent = () => (
  <chakra.div>
    <SectionHeading>Indra Plunge Halter Maxi Dress</SectionHeading>
    <chakra.ul marginBottom="var(--zimm-scale-4xl)">
      <li>Crafted from silk, this halter-neck maxi dress features a plunging V-neckline.</li>
      <li>True to size</li>
    </chakra.ul>
    <SectionHeading>Material</SectionHeading>
    <chakra.ul marginBottom="var(--zimm-scale-4xl)">
      <li>Silk habutae fabrication</li>
    </chakra.ul>
    <SectionHeading>Care</SectionHeading>
    <chakra.ul>
      <li>Dry clean only</li>
    </chakra.ul>
  </chakra.div>
);

const SIZE_GUIDE_CONTENT = <chakra.p>Size guide content — Contentful-driven (SFCC-102), not built here.</chakra.p>;

const TABS: ZimmPdpDrawerTab[] = [
  { id: 'details', label: 'Details & Care', content: <DetailsAndCareContent /> },
  { id: 'size', label: 'Size Guide', content: SIZE_GUIDE_CONTENT },
];

const OpenPdpDrawerExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmPdpDrawer
      isOpen={isOpen}
      onClose={() => setIsOpen(false)}
      size="large"
      tabs={TABS}
      ariaLabel="Product information"
    />
  );
};

export const DetailsAndCareActive: Story = {
  render: () => <OpenPdpDrawerExample />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (ZimmDrawer, which
    // this composes, renders its dialog via Chakra's Portal straight to document.body).
    const doc = within(document.body);
    await expect(await doc.findByRole('dialog')).toBeInTheDocument();
    const activeTab = doc.getByRole('tab', { name: 'Details & Care' });
    await expect(activeTab).toHaveAttribute('aria-selected', 'true');
    await expect(doc.getByText('Indra Plunge Halter Maxi Dress')).toBeInTheDocument();

    // Panel/tab association — a screen reader needs both directions: the tab's aria-controls
    // must resolve to a real element, and the panel's aria-labelledby must resolve back to the
    // currently active tab (not a stale one from a previous render).
    const panel = doc.getByRole('tabpanel');
    const controlsId = activeTab.getAttribute('aria-controls');
    await expect(controlsId).toBe(panel.id);
    await expect(panel.getAttribute('aria-labelledby')).toBe(activeTab.id);
  },
};

export const SwitchingTabsUpdatesContent: Story = {
  render: () => <OpenPdpDrawerExample />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see
    // DetailsAndCareActive's play above).
    const doc = within(document.body);
    await doc.findByRole('dialog');

    await userEvent.click(doc.getByRole('tab', { name: 'Size Guide' }));

    const activeTab = doc.getByRole('tab', { name: 'Size Guide' });
    await expect(activeTab).toHaveAttribute('aria-selected', 'true');
    await expect(doc.getByText(/Contentful-driven/i)).toBeInTheDocument();
    await expect(doc.queryByText('Indra Plunge Halter Maxi Dress')).not.toBeInTheDocument();

    // aria-labelledby must follow the switch, not point at the tab that was active before.
    const panel = doc.getByRole('tabpanel');
    await expect(panel.getAttribute('aria-labelledby')).toBe(activeTab.id);
  },
};

const EmptyPdpDrawerExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmPdpDrawer
      isOpen={isOpen}
      onClose={() => setIsOpen(false)}
      size="large"
      tabs={[]}
      ariaLabel="Product information"
    />
  );
};

/** AC 11 — the shell must still render, without breaking layout, when no tabs are provided. */
export const NoTabContentProvided: Story = {
  render: () => <EmptyPdpDrawerExample />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see
    // DetailsAndCareActive's play above).
    const doc = within(document.body);
    await expect(await doc.findByRole('dialog')).toBeInTheDocument();
  },
};

const InvalidInitialTabIdExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmPdpDrawer
      isOpen={isOpen}
      onClose={() => setIsOpen(false)}
      size="large"
      tabs={TABS}
      // A stale/mistyped id — must not select no tab at all (see zimmPdpDrawer/index.tsx).
      initialTabId="not-a-real-tab-id"
      ariaLabel="Product information"
    />
  );
};

/**
 * `initialTabId` that doesn't match any `tabs` entry falls back to the first tab instead of
 * selecting none — an unmatched id would otherwise leave the whole tablist with `tabIndex={-1}`
 * (ZimmTabs' roving-tabindex pattern only puts the *active* tab in the Tab sequence), making it
 * unreachable by keyboard.
 */
export const InvalidInitialTabIdFallsBackToFirst: Story = {
  render: () => <InvalidInitialTabIdExample />,
  play: async () => {
    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see
    // DetailsAndCareActive's play above).
    const doc = within(document.body);
    await doc.findByRole('dialog');

    const firstTab = doc.getByRole('tab', { name: 'Details & Care' });
    await expect(firstTab).toHaveAttribute('aria-selected', 'true');
    await expect(firstTab).toHaveAttribute('tabindex', '0');
    await expect(doc.getByText('Indra Plunge Halter Maxi Dress')).toBeInTheDocument();
  },
};

